function memoize<This extends object, A, R>(
  method: (this: This, arg: A) => R,
  _context: ClassMethodDecoratorContext<This, (this: This, arg: A) => R>,
) {
  const caches = new WeakMap<This, Map<A, R>>();
  return function (this: This, arg: A): R {
    let cache = caches.get(this);
    if (!cache) caches.set(this, (cache = new Map()));
    if (!cache.has(arg)) cache.set(arg, method.call(this, arg));
    return cache.get(arg)!;
  };
}

class Tax {
  computed = 0;
  vatKobo(amountKobo: number): number {
    this.computed++;
    return Math.round(amountKobo * 0.075);
  }
}

type Vat = (this: Tax, amountKobo: number) => number;
Tax.prototype.vatKobo = memoize(Tax.prototype.vatKobo, { kind: "method", name: "vatKobo" } as ClassMethodDecoratorContext<Tax, Vat>);

const tax = new Tax();
console.log(tax.vatKobo(1_000_000), tax.vatKobo(1_000_000), tax.vatKobo(200_000));
console.log("computed", tax.computed, "times");
